package io.github.leetcode.tree;

import io.github.leetcode.tree.TreeNodes.TreeNode;

import java.util.ArrayList;
import java.util.List;

public class SumRootToLeafNumbers {

    List<String> numbers = new ArrayList<>();

    public int sumNumbers(TreeNode root) {

        getNumbers(root, "");
        int sum = 0;
        for (String num : numbers) {
            sum += Integer.parseInt(num);
        }

        return sum;
    }

    public void getNumbers(TreeNode root, String num) {
        if (root == null) return;

        if (root.left == null && root.right == null) {
            numbers.add(num + root.val);
            return;
        }

        getNumbers(root.left, num + root.val);
        getNumbers(root.right, num + root.val);
    }

}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    void solve(TreeNode* root, int temp, int &sum){

        if(root == NULL){
            return ;
        }

        if(!root -> left and !root -> right){
            temp = temp * 10 + root -> val;
            sum += temp;
            return ;
        }

        temp = temp * 10 + root -> val;

        solve(root -> left, temp, sum);
        solve(root -> right, temp, sum);

    }

public:
    int sumNumbers(TreeNode* root) {

        int temp = 0;
        int sum = 0;

        solve(root, temp, sum);

        return sum;
    }
};

