/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int sumNumbers(TreeNode* root) {
        int ans=0,sum=0,depth=0;
        while(root)
        {
            if(!root->left)
            {
                sum=sum*10+root->val;
                if(!root->right)
                    ans+=sum;
                root=root->right;
            }
            else
            {
                depth=1;
                TreeNode* prev=root->left;
                while(prev->right and prev->right!=root)
                    prev=prev->right,depth+=1;
                if(!prev->right)
                {
                    prev->right=root;
                    sum=sum*10+root->val;
                    root=root->left;
                }
                else
                {
                    prev->right=nullptr;
                    if(!prev->left)
                        ans+=sum;
                    sum/=pow(10,depth);
                    root=root->right;
                }
            }
        }
        return ans;
    }
};

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, x):
#         self.val = x
#         self.left = None
#         self.right = None

class Solution:
    # @param {TreeNode} root
    # @return {integer}
    def sumNumbers(self, root):
        if not root:
            return 0
        self.sum = 0
        self.visitNode(root, str(root.val))
        return self.sum

    def visitNode(self, node, v):
        if not node.left and not node.right:
            self.sum += int(v)

        if node.left:
            self.visitNode(node.left, v+str(node.left.val))
        if node.right:
            self.visitNode(node.right, v+str(node.right.val))
